public class Main {
    public static void main(String[] args) {
        int[] a = {2, 3};
        // 배열 자체가 아니라 참조값을 복사해요.
        int[] b = a;
        b[0] = 7;
        System.out.println(a[0]);
    }
}

public class Main {
    public static void main(String[] args) {
        int[][] a = {{2}, {3}};
        // 바깥 배열만 새로 만들어요.
        int[][] b = a.clone();
        b[0][0] = 7;
        System.out.println(a[0][0]);
    }
}

class Stock {
    int count;
    // 각 객체의 재고 값을 따로 준비해요.
    Stock(int count) { this.count = count; }
}
class Changes {
    static void change(Stock value) {
        // 복사된 참조값으로 같은 객체의 필드를 바꿔요.
        value.count = 7;
    }
}

public class Main {
    public static void main(String[] args) {
        Stock a = new Stock(2);
        Changes.change(a);
        System.out.println(a.count);
    }
}

class Stock {
    int count;
    // 각 객체의 재고 값을 따로 준비해요.
    Stock(int count) { this.count = count; }
}
class Changes {
    static Stock replace(Stock value) {
        // 인수 이름만 새 객체로 연결하고 그 참조값을 반환해요.
        value = new Stock(9);
        return value;
    }
}

public class Main {
    public static void main(String[] args) {
        Stock a = new Stock(2);
        Changes.replace(a);
        System.out.println(a.count);
    }
}

