class Stock {
    int count;
    // 각 객체의 재고 값을 따로 준비해요.
    Stock(int count) { this.count = count; }
}

public class Main {
    public static void main(String[] args) {
        Stock a = new Stock(2);
        Stock b = a;
        b.count += 3;
        // b만 새 대상으로 옮겨요.
        b = new Stock(9);
        System.out.println(a.count + ":" + b.count);
    }
}

