public class Main {
    static class Order {
        int[] quantities;
        Order(int[] source) { quantities = source; }
        void add(int value) { quantities[0] += value; }
    }
    public static void main(String[] args) {
        int[] source = {2, 4};
        int added = 3;
        Order first = new Order(source);
        Order second = new Order(source);
        first.add(added);
        System.out.print(source[0] + " " + first.quantities[0] + " " + second.quantities[0]);
    }
}

tasks.solution:
public class Main {
    static class Order {
        int[] quantities;
        Order(int[] source) { quantities = source.clone(); }
        void add(int value) { quantities[0] += value; }
    }
    public static void main(String[] args) {
        int[] source = {2, 4};
        int added = 3;
        Order first = new Order(source);
        Order second = new Order(source);
        first.add(added);
        System.out.print(source[0] + " " + first.quantities[0] + " " + second.quantities[0]);
    }
}
